<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <h4 class="modal-title">No : {{ item.Id }}</h4>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="callout callout-secondary p-3 mb-3">
            <!-- title row -->
            <div class="row">
              <div class="col-12">
                <h4>
                  <i class="fas fa-globe"></i> 정보:
                  <small class="float-right"
                    >조회일:
                    {{
                      $date(item.CreatedAt).format("YYYY.MM.DD HH:mm")
                    }}</small
                  >
                </h4>
              </div>
              <!-- /.col -->
            </div>
            <!-- info row -->
            <div class="row invoice-info">
              <div class="col-sm-4 invoice-col">
                <b>전화번호:</b> {{ item.Contact }}<br />
                <b>거래유형:</b> {{ item.TransactionType }}<br />
                <b>주택보유:</b> {{ item.HouseOwnership }}<br />
                <b>매물유형:</b> {{ item.PropertyType }}<br />
              </div>
              <!-- /.col -->
              <div class="col-sm-4 invoice-col">
                <b>가용금액:</b> {{ numberToKorean2(item.AvailableAmount)
                }}<br />
                <b>신용점수:</b> {{ item.CreditScore }}<br />
                <b>대출비율/대출금액:</b> {{ item.LoanRate }}% /
                {{
                  numberToKorean2(
                    item.AvailableAmount * (item.LoanRate / 100 + 1)
                  )
                }}<br />
                <b>상담진행상태:</b> {{ item.Contact }}<br />
              </div>
              <!-- /.col -->
              <div class="col-sm-4 invoice-col">
                <b>담당직원:</b>
                {{
                  item.TeamLeaderName != null
                    ? item.TeamLeaderName
                    : item.AdminName != null
                    ? item.AdminName
                    : null
                }}<br />
                <b>관심지역(광역):</b> {{ item.CityName }}<br />
                <b>시/군/구:</b> {{ item.CountyName }}<br />
              </div>
              <!-- /.col -->
            </div>
          </div>
          <div class="callout callout-secondary">
            <h5><i class="fas fa-star"></i> 관심매물 리스트:</h5>
            <table class="table table-striped">
              <thead>
                <tr>
                  <th>No</th>
                  <th>아파트단지</th>
                  <th>평형</th>
                  <th>네이버호가(최고)</th>
                  <th>네이버호가(최저)</th>
                  <th>국토교통부실거래가(최고)</th>
                  <th>국토교통부실거래가(최저)</th>
                  <th>리뷰</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(ii, idx) in itemList" v-bind:key="'iitab_' + ii.Id">
                  <td>{{ idx + 1 }}</td>
                  <td>{{ ii.Name }}</td>
                  <td>{{ Math.round(ii.SpecSply * 100) / 100 }}</td>
                  <td>{{ numberToKorean2(ii.NMaxPrice) }}</td>
                  <td>{{ numberToKorean2(ii.NMinPrice) }}</td>
                  <td>{{ numberToKorean2(ii.KMaxPrice) }}</td>
                  <td>{{ numberToKorean2(ii.KMinPrice) }}</td>
                  <td>{{ ii.ReviewCount }}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div class="callout callout-secondary">
            <template v-if="memoFlag">
              <h5><i class="fas fa-info"></i> 메모:</h5>
              <textarea v-model="item.Memo" class="form-control" />
              <br />
              <div class="row no-print">
                <div class="col-12">
                  <button
                    type="button"
                    class="btn btn-info float-right"
                    style="margin-right: 5px"
                    @click="memoSave"
                  >
                    <i class="fas fa-pen-square"></i> 저장
                  </button>
                </div>
              </div>
            </template>
            <template v-else>
              <h5><i class="fas fa-info"></i> 메모:</h5>
              <div
                v-if="item.Memo"
                v-html="item.Memo.replace(/(?:\r\n|\r|\n)/g, '<br />')"
              ></div>
              <div class="row no-print">
                <div class="col-12">
                  <button
                    type="button"
                    class="btn btn-info float-right"
                    style="margin-right: 5px"
                    @click="memoFlag = true"
                  >
                    <i class="fas fa-pen-square"></i> 메모작성하기
                  </button>
                </div>
              </div>
            </template>
          </div>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
export default {
  name: "ConsultViewModal",
  props: { item: Object },
  components: {},
  data() {
    return { memoFlag: false, itemList: [] };
  },
  created() {
    this.getList();
  },
  mounted() {},
  methods: {
    getList() {
      this.$apiGET("/admin/consults/detail?consultId=" + this.item.Id).then(
        ({ data }) => {
          this.itemList = data.d;
        }
      );
    },
    memoSave() {
      this.$apiPOST("/admin/consult/memo", {
        ConsultId: this.item.Id,
        Memo: this.item.Memo,
      }).then(({ data }) => {
        this.itemList = data.d;
        this.memoFlag = false;
      });
    },
    numberToKorean2(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          resultArray[i] = unitResult;
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }
      resultString = resultString.slice(0, -1);
      return resultString + "원";
    },
  },
};
</script>
