import Vue from "vue";
import VueRouter from "vue-router";
// import VueCookies from "vue-cookies";
import Main from "../components/Main";
import Main2 from "../components/Main2";
import Login from "../components/Login";
import IpManagement from "../components/IpManagement";
import Notice from "../components/Notice";
import Questions from "../components/Questions";
import Apartment from "../components/Apartment";
import ReviewManagement from "../components/ReviewManagement";
import ConsultManagement from "../components/ConsultManagement";
import TeamManagement from "../components/TeamManagement";
import Sms from "../components/Sms";
import KakaoSms from "../components/KakaoSms";
import VueCookies from "vue-cookies";

Vue.use(VueRouter);

const routes = [
  {
    path: "/admin",
    component: Main,
    name: "Main",
    props: true,
  },
  {
    path: "/admin/main2",
    component: Main2,
    name: "Main2",
    props: true,
  },
  {
    path: "/admin/ip",
    component: IpManagement,
    name: "Ip",
    props: true,
  },
  {
    path: "/admin/notice",
    component: Notice,
    name: "Notice",
    props: true,
  },
  {
    path: "/admin/qna",
    component: Questions,
    name: "Questions",
    props: true,
  },
  {
    path: "/admin/apartment",
    component: Apartment,
    name: "Apartment",
    props: true,
  },
  {
    path: "/admin/review",
    component: ReviewManagement,
    name: "ReviewManagement",
    props: true,
  },
  {
    path: "/admin/conman",
    component: ConsultManagement,
    name: "ConsultManagement",
    props: true,
  },
  {
    path: "/admin/team",
    component: TeamManagement,
    name: "TeamManagement",
    props: true,
  },
  {
    path: "/admin/sms",
    component: Sms,
    name: "Sms",
    props: true,
  },
  {
    path: "/admin/kakao",
    component: KakaoSms,
    name: "KakaoSms",
    props: true,
  },
  {
    path: "/admin/login",
    component: Login,
    name: "Login",
    props: true,
    meta: { unauthorized: true },
  },
];

const router = new VueRouter({
  mode: "history",
  base: process.env.BASE_URL,
  routes,
});

router.beforeEach(async (to, from, next) => {
  if (
    to.matched.some((record) => record.meta.unauthorized) ||
    VueCookies.get("jwt")
  ) {
    return next();
  }

  alert("로그인 해주세요");

  return next("/login");
});

export default router;
