<template>
  <div class="wrapper">
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>카카오 알림톡 발송</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row p-2">
            <div class="col-sm-6"></div>
            <div class="col-sm-6">
              <button
                type="button"
                class="btn btn-primary float-right"
                style="margin-left: 5px"
                @click="sendsms"
                disabled
              >
                알림톡 전송
              </button>
            </div>
          </div>
          <div class="card">
            <!-- /.card-header -->
            <div class="card-body">
              <div class="row">
                <div class="col-sm-12">
                  <!-- textarea -->
                  <div class="form-group">
                    <label>알림톡 내용</label>
                    <textarea
                      class="form-control"
                      rows="3"
                      placeholder="내용"
                      v-model="content"
                      @input="fnChkByte"
                    ></textarea>
                  </div>
                </div>
              </div>
              <div class="row">
                <div class="col-sm-12" style="text-align: right">
                  {{ totalByte }}byte
                </div>
              </div>
            </div>
            <!-- /.card-body -->
          </div>
        </div>
      </section>
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";

export default {
  name: "KakaoSms",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
  },
  data() {
    return { content: "", totalByte: 0 };
  },
  updated() {},
  created() {},
  mounted() {},
  methods: {
    sendsms() {
      this.fnChkByte();
      if (this.totalByte <= 90) {
        this.$apiPOST("/admin/sendsms", { Text: this.content }).then((re) => {
          console.log(re);
          alert("전송 완료");
        });
      } else {
        alert("90byte 이하의 내용으로 작성해주세요.");
      }
    },
    fnChkByte() {
      //   const maxByte = 90; //최대 100바이트
      const text_val = this.content; //입력한 문자
      const text_len = text_val.length; //입력한 문자수

      let totalByte = 0;
      for (let i = 0; i < text_len; i++) {
        const each_char = text_val.charAt(i);
        const uni_char = escape(each_char); //유니코드 형식으로 변환
        if (uni_char.length > 4) {
          // 한글 : 2Byte
          totalByte += 2;
        } else {
          // 영문,숫자,특수문자 : 1Byte
          totalByte += 1;
        }
      }
      this.totalByte = totalByte;
    },
  },
};
</script>
