<template>
  <div class="wrapper">
    <Modal1
      v-if="showModal"
      @close="closeModal"
      @searchOption="searchOption"
      :searchOptionData="searchOptionData"
    ></Modal1>
    <Modal2
      v-if="selectModal.length > 0"
      @close="closeModal"
      @saveAdmin="saveAdmin"
      :selectList="selectModal"
    ></Modal2>
    <consult-view-modal
      v-if="showViewModal != null"
      @close="closeModal"
      :item="itemList[showViewModal]"
    ></consult-view-modal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>미배정 문의 관리</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-12 col-md-4">
                <button
                  type="button"
                  class="btn btn-info float-left"
                  style="margin-left: 5px"
                  @click="showModal = true"
                >
                  <i class="fas fa-search-plus"></i> 검색하기(필터)
                </button>
              </div>
              <div class="col-sm-12 col-md-8">
                <button
                  type="button"
                  class="btn btn-success float-right"
                  style="margin-right: 5px"
                  @click="btnAdminOn"
                >
                  <i class="fas fa-air-freshener"></i> 상담직원 배정
                </button>
                <button
                  type="button"
                  class="btn btn-primary float-right"
                  style="margin-right: 5px"
                  @click="makeExcelFile"
                >
                  <i class="fas fa-download"></i> Exel 내려받기
                </button>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>Id</th>
                          <th>조회일</th>
                          <th>가용금액</th>
                          <th>대출비율</th>
                          <th>대출금액</th>
                          <th>신용점수</th>
                          <th>주택보유</th>
                          <th>광역지역</th>
                          <th>시/군/구</th>
                          <th>거래유형</th>
                          <th>매물유형</th>
                          <th>관심 아파트</th>
                          <th>IP</th>
                          <th>담당직원</th>
                          <th
                            class="p-0 text-center"
                            style="vertical-align: middle"
                          >
                            <button
                              type="button"
                              class="btn btn-Default"
                              @click="allCheck"
                            >
                              V
                            </button>
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i0_' + item.Id"
                          style="font-size: 13px"
                          @click="showViewModal = idx"
                        >
                          <td>{{ item.Id }}</td>
                          <td>{{ item.Contact }}</td>
                          <td>
                            {{ $date(item.CreatedAt).format("YY.MM.DD HH:mm") }}
                          </td>
                          <td>{{ numberToKorean2(item.AvailableAmount) }}</td>
                          <td>{{ item.LoanRate }}%</td>
                          <td>
                            {{
                              numberToKorean2(
                                item.AvailableAmount * (item.LoanRate / 100 + 1)
                              )
                            }}
                          </td>
                          <td>{{ item.CreditScore }}</td>
                          <td>{{ item.HouseOwnership }}</td>
                          <td>{{ item.CityName }}</td>
                          <td>{{ item.CountyName }}</td>
                          <td>{{ item.TransactionType }}</td>
                          <td>{{ item.PropertyType }}</td>
                          <td>{{ item.FavoriteApartmentName }}</td>
                          <td>{{ item.IP }}</td>
                          <td
                            class="p-0 text-center"
                            style="vertical-align: middle"
                          >
                            <button
                              v-if="
                                item.AdminName == null &&
                                item.TeamLeaderName == null
                              "
                              type="button"
                              class="btn btn-success"
                              @click.stop
                              @click="selectModal.push(item.Id)"
                            >
                              선택
                            </button>
                            <button
                              v-else-if="item.TeamLeaderName != null"
                              type="button"
                              class="btn btn-outline-secondary"
                              @click.stop
                              @click="selectModal.push(item.Id)"
                            >
                              {{ item.TeamLeaderName }}
                            </button>
                            <button
                              v-else
                              type="button"
                              class="btn btn-outline-secondary"
                              @click.stop
                              @click="selectModal.push(item.Id)"
                            >
                              {{ item.AdminName }}
                            </button>
                          </td>
                          <td
                            class="p-0 text-center"
                            style="vertical-align: middle"
                          >
                            <input
                              type="checkbox"
                              v-model="item.isCheck"
                              @click.stop
                            />
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import Xlsx from "xlsx";
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import Modal1 from "./Modal1.vue";
import Modal2 from "./Modal2.vue";
import ConsultViewModal from "./ConsultViewModal.vue";

export default {
  name: "Main2",
  props: {
    msg: String,
  },
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    Modal1,
    Modal2,
    ConsultViewModal,
  },
  data() {
    return {
      itemList: [],
      page: 1,
      itemCount: null,
      showModal: false,
      showViewModal: null,
      selectModal: [],
      pageData: null,
      searchOptionData: {
        searchType: null,
        search: null,
        minAmount: null,
        maxAmount: null,
        creditScore: null,
        startDate: null,
        endDate: null,
        transactionType: null,
        houseOwnership: null,
        propertyType: null,
      },
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    makeExcelFile() {
      this.$apiGET(
        "/admin/consults/search?searchType=" +
          this.searchOptionData.searchType +
          "&search=" +
          this.searchOptionData.search +
          "&minAmount=" +
          this.searchOptionData.minAmount +
          "&maxAmount=" +
          this.searchOptionData.maxAmount +
          "&creditScore=" +
          this.searchOptionData.creditScore +
          "&startDate=" +
          this.searchOptionData.startDate +
          "&endDate=" +
          this.searchOptionData.endDate +
          "&transactionType=" +
          this.searchOptionData.transactionType +
          "&houseOwnership=" +
          this.searchOptionData.houseOwnership +
          "&propertyType=" +
          this.searchOptionData.propertyType +
          "&Unassigned=1"
      ).then(({ data }) => {
        const itemList_ = data.d;
        const workBook = Xlsx.utils.book_new();
        const workSheet = Xlsx.utils.json_to_sheet(itemList_);
        Xlsx.utils.book_append_sheet(workBook, workSheet, "미배정문의관리");
        Xlsx.writeFile(workBook, "미배정문의관리.xlsx");
      });
    },
    saveAdmin(adminName) {
      for (let i = 0; i < this.itemList.length; i++) {
        for (let j = 0; j < this.selectModal.length; j++) {
          if (this.itemList[i].Id == this.selectModal[j]) {
            this.itemList[i].AdminName = adminName;
            break;
          }
        }
      }
      this.itemList.push(1);
      this.itemList.pop();
      this.selectModal = [];
    },
    searchOption(op) {
      this.searchOptionData = op;
      this.showModal = false;
      this.getItems(1);
    },
    btnAdminOn() {
      for (let i = 0; i < this.itemList.length; i++) {
        if (this.itemList[i].isCheck) {
          this.selectModal.push(this.itemList[i].Id);
        }
      }
    },
    allCheck() {
      let tureCnt = 0;
      for (let i = 0; i < this.itemList.length; i++) {
        tureCnt += this.itemList[i].isCheck;
      }

      let flagType = false;
      if (tureCnt < 5) {
        flagType = true;
      }

      for (let i = 0; i < this.itemList.length; i++) {
        this.itemList[i].isCheck = flagType;
        this.itemList.push(1);
        this.itemList.pop();
      }
    },
    getItems(pg) {
      this.$apiGET(
        "/admin/consults/search?page=" +
          pg +
          "&searchType=" +
          this.searchOptionData.searchType +
          "&search=" +
          this.searchOptionData.search +
          "&minAmount=" +
          this.searchOptionData.minAmount +
          "&maxAmount=" +
          this.searchOptionData.maxAmount +
          "&creditScore=" +
          this.searchOptionData.creditScore +
          "&startDate=" +
          this.searchOptionData.startDate +
          "&endDate=" +
          this.searchOptionData.endDate +
          "&transactionType=" +
          this.searchOptionData.transactionType +
          "&houseOwnership=" +
          this.searchOptionData.houseOwnership +
          "&propertyType=" +
          this.searchOptionData.propertyType +
          "&Unassigned=1"
      ).then(({ data }) => {
        this.itemList = data.d;

        for (let i = 0; i < this.itemList.length; i++) {
          this.itemList[i].isCheck = false;
        }

        this.itemCount = data.info[0].ItemCount;
        this.page = pg;

        this.pageData = this.pageDataSetting(this.itemCount, 10, 10, this.page);
      });
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    closeModal() {
      this.showModal = false;
      this.selectModal = [];
      this.showViewModal = null;
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
    clickList() {
      this.$router.push({
        name: "CreateReview",
        query: { name: "Query 프로그래밍 방식", age: 2 },
      });
    },
    clickParams() {
      this.$router.push({
        name: "CreateReview",
        params: { name: "Params 프로그래밍 방식", age: 2 },
      });
    },
    numberToKorean2(number) {
      var inputNumber = number < 0 ? false : number;
      var unitWords = ["", "만 ", "억 ", "조 ", "경 "];
      var splitUnit = 10000;
      var splitCount = unitWords.length;
      var resultArray = [];
      var resultString = "";

      for (var i = 0; i < splitCount; i++) {
        var unitResult =
          (inputNumber % Math.pow(splitUnit, i + 1)) / Math.pow(splitUnit, i);
        unitResult = Math.floor(unitResult);
        if (unitResult > 0) {
          resultArray[i] = unitResult;
        }
      }

      for (let i = 0; i < resultArray.length; i++) {
        if (!resultArray[i]) continue;
        resultString = String(resultArray[i]) + unitWords[i] + resultString;
      }

      return resultString + "원";
    },
  },
};
</script>
