<template>
  <div class="wrapper">
    <NoticeModal
      v-if="showModal || selectItemIdx != null"
      @close="closeModal"
      @createNotice="createNotice"
      @deleteNotice="deleteNotice"
      :item="itemList[selectItemIdx]"
      :editMode="editMode"
    ></NoticeModal>
    <HeaderMenu></HeaderMenu>
    <SideMenu></SideMenu>
    <div class="content-wrapper">
      <!-- Content Header (Page header) -->
      <section class="content-header">
        <div class="container-fluid">
          <div class="row mb-2">
            <div class="col-sm-6">
              <h1>공지사항</h1>
            </div>
            <div class="col-sm-6"></div>
          </div>
        </div>
        <!-- /.container-fluid -->
      </section>

      <section class="content">
        <div class="container-fluid">
          <div class="row">
            <div class="row p-2">
              <div class="col-sm-12">
                <button
                  type="button"
                  class="btn btn-primary float-right"
                  style="margin-left: 5px"
                  @click="(showModal = true), (editMode = 0)"
                >
                  <i class="fas fa-pen"></i> 작성
                </button>
              </div>
            </div>
            <div class="col-12">
              <!-- Main content -->
              <div class="invoice p-3 mb-3">
                <!-- title row -->
                <div class="row">
                  <div class="col-sm-12">
                    <table
                      id="example1"
                      class="
                        table table-bordered table-striped
                        dataTable
                        dtr-inline
                      "
                      aria-describedby="example1_info"
                    >
                      <thead>
                        <tr>
                          <th>No</th>
                          <th>작성일자</th>
                          <th>제목</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr
                          v-for="(item, idx) in itemList"
                          v-bind:key="'i2_' + item.Id"
                          @click="(selectItemIdx = idx), (editMode = 1)"
                        >
                          <td>{{ item.Id }}</td>
                          <td>
                            {{ $date(item.CreatedAt).format("YYYY.MM.DD") }}
                          </td>
                          <td>
                            {{ item.Title }}
                            <button
                              type="button"
                              class="btn btn-danger float-right"
                              @click.stop
                              @click="deleteNotice({ Id: item.Id })"
                            >
                              삭제
                            </button>
                            <button
                              type="button"
                              class="btn btn-success float-right"
                              @click.stop
                              @click="(selectItemIdx = idx), (editMode = 2)"
                            >
                              수정
                            </button>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
                <div class="row">
                  <div class="col-sm-12">
                    <Pagination
                      :pageData="pageData"
                      @paging="pagingMethod"
                    ></Pagination>
                  </div>
                </div>
              </div>
              <!-- /.invoice -->
            </div>

            <!-- /.col -->
          </div>
          <!-- /.row -->
        </div>
        <!-- /.container-fluid -->
      </section>
      <!-- /.content -->
    </div>
  </div>
</template>

<script>
import SideMenu from "./SideMenu.vue";
import HeaderMenu from "./HeaderMenu.vue";
import Pagination from "./Pagination.vue";
import NoticeModal from "../components/NoticeModal";

export default {
  name: "Notice",
  props: {},
  components: {
    SideMenu,
    HeaderMenu,
    Pagination,
    NoticeModal,
  },
  data() {
    return {
      pageType: false,
      editMode: null,
      selectItemIdx: null,
      itemList: [],
      page: 1,
      itemCount: null,
      showModal: false,
      showViewModal: null,
      selectModal: [],
      pageData: null,
    };
  },
  updated() {},
  created() {
    this.init();
  },
  mounted() {},
  methods: {
    // ozit_timer_test() {
    //   window.Android.SetWebViewVisible();
    // },
    init() {
      this.getItems(this.page);
    },
    closeModal() {
      this.showModal = false;
      this.selectItemIdx = null;
      this.editMode = null;
    },
    getItems(pg) {
      this.$apiGET("/admin/notices?page=" + pg).then(({ data }) => {
        this.itemList = data.d;
        this.itemCount = data.info[0].ItemCount;
        this.page = pg;

        this.pageData = this.pageDataSetting(this.itemCount, 10, 10, this.page);
      });
    },
    pageDataSetting(total, limit, block, page) {
      const totalPage = Math.ceil(total / limit);
      let currentPage = page;
      const first =
        currentPage > 1 ? parseInt(currentPage, 10) - parseInt(1, 10) : null;
      const end =
        totalPage !== currentPage
          ? parseInt(currentPage, 10) + parseInt(1, 10)
          : null;

      let startIndex = (Math.ceil(currentPage / block) - 1) * block + 1;
      let endIndex =
        startIndex + block > totalPage ? totalPage : startIndex + block - 1;
      let list = [];
      for (let index = startIndex; index <= endIndex; index++) {
        list.push(index);
      }
      return { first, end, list, currentPage };
    },
    pagingMethod(pg) {
      this.getItems(pg);
    },
    createNotice(param) {
      this.$apiPOST("/admin/notice", param).then(() => {
        this.getItems(this.page);
        this.closeModal();
      });
    },
    deleteNotice(param) {
      this.$apiPOST("/admin/delete/notice", param).then(() => {
        this.getItems(this.page);
        this.closeModal();
      });
    },
  },
};
</script>
