<template>
  <div
    class="modal fade show"
    id="modal-default"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h4 class="modal-title">검색하기(필터)</h4>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="card-body">
            <div class="form-group">
              <div class="row">
                <div class="col-sm-3">
                  <label>검색하기:</label>
                </div>

                <div class="col-sm-9">
                  <div class="row">
                    <div class="col-sm-4">
                      <select class="form-control" v-model="searchType">
                        <option :value="null">선택</option>
                        <option>전화번호</option>
                        <option>아파트단지</option>
                        <option>상담사</option>
                        <option>지역</option>
                      </select>
                    </div>
                    <div class="col-sm-8">
                      <input
                        type="text"
                        class="form-control"
                        data-target="#reservationdate"
                        v-model="search"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div class="form-group">
              <div class="row">
                <div class="col-sm-3">
                  <label>가용금액:</label>
                </div>
                <div class="col-sm-9">
                  <div class="row">
                    <div class="col-sm-5">
                      <input
                        type="number"
                        class="form-control datetimepicker-input"
                        data-target="#reservationdate"
                        v-model="minAmount"
                      />
                    </div>
                    <div
                      class="col-sm-2"
                      style="display: inline-block; text-align: center"
                    >
                      <h4>~</h4>
                    </div>
                    <div class="col-sm-5">
                      <input
                        type="number"
                        class="form-control datetimepicker-input"
                        data-target="#reservationdate"
                        v-model="maxAmount"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <!-- Date and time -->
            <div class="form-group">
              <div class="row">
                <div class="col-sm-4">
                  <label>신용점수:</label>
                </div>
                <div class="col-sm-8">
                  <div class="row">
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      700점 미만
                      <input
                        type="radio"
                        name="radio1"
                        value="700점 미만"
                        v-model="creditScore"
                      />
                    </div>
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      700점 이상
                      <input
                        type="radio"
                        name="radio1"
                        value="700점 이상"
                        v-model="creditScore"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <!-- /.form group -->
            <!-- Date range -->
            <div class="form-group">
              <div class="row">
                <div class="col-sm-2">
                  <label>조회일:</label>
                </div>
                <div class="col-sm-10">
                  <div class="row">
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      <input type="date" name="radio1" v-model="startDate" />
                    </div>
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      <input type="date" name="radio1" v-model="endDate" />
                    </div>
                  </div>
                </div>
              </div>

              <!-- /.input group -->
            </div>
            <!-- /.form group -->

            <!-- Date and time range -->
            <div class="form-group">
              <div class="row">
                <div class="col-sm-4">
                  <label>거래 유형:</label>
                </div>
                <div class="col-sm-8">
                  <div class="row">
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      매매
                      <input
                        type="radio"
                        name="radio2"
                        value="매매"
                        v-model="transactionType"
                      />
                    </div>
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      전세
                      <input
                        type="radio"
                        name="radio2"
                        value="전세"
                        v-model="transactionType"
                      />
                    </div>
                  </div>
                </div>
              </div>

              <!-- /.input group -->
            </div>
            <!-- /.form group -->

            <!-- Date and time range -->
            <div class="form-group">
              <div class="row">
                <div class="col-sm-4">
                  <label>주택보유여부:</label>
                </div>
                <div class="col-sm-8">
                  <div class="row">
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      1주택자 이상
                      <input
                        type="radio"
                        name="radio3"
                        value="1주택 이상 보유"
                        v-model="houseOwnership"
                      />
                    </div>
                    <div
                      class="col-sm-6"
                      style="display: inline-block; text-align: right"
                    >
                      무주택자
                      <input
                        type="radio"
                        name="radio3"
                        value="무주택"
                        v-model="houseOwnership"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div class="form-group">
              <div class="row">
                <div class="col-sm-4">
                  <label>매물 유형:</label>
                </div>
                <div class="col-sm-8">
                  <div class="row">
                    <div
                      class="col-sm-4"
                      style="display: inline-block; text-align: center"
                    >
                      아파트
                      <input
                        type="radio"
                        name="radio4"
                        value="아파트"
                        v-model="propertyType"
                      />
                    </div>
                    <div
                      class="col-sm-4"
                      style="display: inline-block; text-align: center"
                    >
                      오피스텔
                      <input
                        type="radio"
                        name="radio4"
                        value="오피스텔"
                        v-model="propertyType"
                      />
                    </div>
                    <div
                      class="col-sm-4"
                      style="display: inline-block; text-align: center"
                    >
                      기타
                      <input
                        type="radio"
                        name="radio4"
                        value="기타"
                        v-model="propertyType"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <!-- /.form group -->
          </div>
        </div>
        <div class="modal-footer justify-content-between">
          <button
            type="button"
            class="btn btn-default"
            data-dismiss="modal"
            @click="$emit('close')"
          >
            닫기
          </button>
          <button
            type="button"
            class="btn btn-primary"
            @click="
              $emit('searchOption', {
                searchType: searchType,
                search: search,
                minAmount: minAmount,
                maxAmount: maxAmount,
                creditScore: creditScore,
                startDate: startDate,
                endDate: endDate,
                transactionType: transactionType,
                houseOwnership: houseOwnership,
                propertyType: propertyType,
              })
            "
          >
            조회하기
          </button>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  name: "Modal1",
  props: { searchOptionData: Object },
  components: {},
  data() {
    return {
      searchType: null,
      search: null,
      minAmount: null,
      maxAmount: null,
      creditScore: null,
      startDate: null,
      endDate: null,
      transactionType: null,
      houseOwnership: null,
      propertyType: null,
    };
  },
  created() {},
  mounted() {
    this.searchType = this.searchOptionData.searchType;
    this.search = this.searchOptionData.search;
    this.minAmount = this.searchOptionData.minAmount;
    this.maxAmount = this.searchOptionData.maxAmount;
    this.creditScore = this.searchOptionData.creditScore;
    this.startDate = this.searchOptionData.startDate;
    this.endDate = this.searchOptionData.endDate;
    this.transactionType = this.searchOptionData.transactionType;
    this.houseOwnership = this.searchOptionData.houseOwnership;
    this.propertyType = this.searchOptionData.propertyType;
  },
  methods: {},
};
</script>
