<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <template v-if="!editMode && pageType == 0">
            <h4 class="modal-title">상담사 추가</h4>
          </template>
          <template v-else-if="!editMode && pageType == 1">
            <h4 class="modal-title">팀장 추가</h4>
          </template>
          <template v-else>
            <h4 class="modal-title">{{ tgItem.Id }}</h4>
          </template>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <!-- <div class="card-body">
            <textarea
              v-model="tgItem.Content"
              placeholder="내용"
              class="form-control"
            />
          </div> -->
          <div class="card-body login-card-body">
            <template v-if="pageType == 0">
              <div class="input-group mb-3"><b>소속팀장:</b></div>

              <div class="input-group mb-3">
                <select class="form-control" v-model="tgItem.TeamLeaderId">
                  <option :value="null">팀장선택</option>
                  <option
                    v-for="tl in teamLeaderList"
                    v-bind:key="'leader_' + tl.Id"
                    :value="tl.Id"
                  >
                    {{ tl.Name }}
                  </option>
                </select>
                <!-- <div class="input-group-append">
                  <button
                    type="submit"
                    class="btn btn-md btn-default"
                    @click="searchAdmin"
                  >
                    <i class="fa fa-search"></i>
                  </button>
                </div> -->

                <div class="input-group-append">
                  <div class="input-group-text">
                    <span class="fas fa-caret-down"></span>
                  </div>
                </div>
              </div>
            </template>
            <div class="input-group mb-3"><b>이름:</b></div>
            <div class="input-group mb-3">
              <input
                type="text"
                placeholder="이름"
                class="form-control"
                v-model="tgItem.Name"
              />
              <div class="input-group-append">
                <div class="input-group-text">
                  <span class="fas fa-user"></span>
                </div>
              </div>
            </div>
            <div class="input-group mb-3"><b>ID:</b></div>
            <div class="input-group mb-3">
              <input
                placeholder="ID"
                class="form-control"
                v-model="tgItem.Username"
                :disabled="editMode"
              />
              <div class="input-group-append">
                <div class="input-group-text">
                  <span class="fas fa-envelope"></span>
                </div>
              </div>
            </div>
            <div class="input-group mb-3"><b>PW:</b></div>
            <div class="input-group mb-3">
              <input
                placeholder="PW"
                class="form-control"
                v-model="tgItem.Password"
              />
              <div class="input-group-append">
                <div class="input-group-text">
                  <span class="fas fa-lock"></span>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="modal-footer justify-content">
          <button
            v-if="editMode"
            type="button"
            class="btn btn-success float-right"
            @click="createNoti"
          >
            수정
          </button>
          <button
            v-else
            type="button"
            class="btn btn-primary float-right"
            @click="addAdmin"
          >
            추가
          </button>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
export default {
  name: "ConsultManagementModal",
  props: { item: Object, editMode: Boolean, pageType: Number },
  components: {},
  data() {
    return {
      teamLeaderList: [],
      tgItem: {
        TeamLeaderId: null,
        TeamLeaderName: "",
        Name: "",
        Username: "",
        Password: "",
      },
      tgEditMode: null,
    };
  },
  created() {
    if (this.editMode) {
      this.tgItem = { ...this.item };
    }

    if (this.pageType == 0) {
      this.searchAdmin();
    }
  },
  mounted() {},
  methods: {
    searchAdmin() {
      this.$apiGET("/admin/admins2/teamleaders").then(({ data }) => {
        this.teamLeaderList = data.d;
      });
    },
    createNoti() {
      if (this.pageType == 0) {
        this.$emit("editAdmin", {
          Id: this.tgItem.Id,
          Name: this.tgItem.Name,
          Password: this.tgItem.Password,
          Username: this.tgItem.Username,
          TeamLeaderId: this.tgItem.TeamLeaderId,
        });
      } else {
        this.$emit("editAdmin", {
          Id: this.tgItem.Id,
          Name: this.tgItem.Name,
          Password: this.tgItem.Password,
          Username: this.tgItem.Username,
        });
      }
    },
    addAdmin() {
      if (this.pageType == 0) {
        this.$emit("addAdmin", {
          Name: this.tgItem.Name,
          Password: this.tgItem.Password,
          Username: this.tgItem.Username,
          TeamLeaderId: this.tgItem.TeamLeaderId,
        });
      } else {
        this.$emit("addAdmin", {
          Name: this.tgItem.Name,
          Password: this.tgItem.Password,
          Username: this.tgItem.Username,
        });
      }
    },
  },
};
</script>
