<template>
  <div
    class="modal fade show"
    id="modal-xl"
    style="display: block; padding-right: 17px"
    aria-modal="true"
    role="dialog"
  >
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <template v-if="tgEditMode == 0">
            <input
              type="text"
              class="form-control"
              placeholder="제목"
              v-model="tgItem.Title"
            />
          </template>
          <template v-else-if="tgEditMode == 1">
            <h4 class="modal-title">{{ tgItem.Title }}</h4>
          </template>
          <template v-else>
            <input
              type="text"
              class="form-control"
              placeholder="제목"
              v-model="tgItem.Title"
            />
          </template>
          <button
            type="button"
            class="close"
            data-dismiss="modal"
            aria-label="Close"
          >
            <span aria-hidden="true" @click="$emit('close')">×</span>
          </button>
        </div>
        <div class="modal-body">
          <div class="card-body">
            <template v-if="tgEditMode == 1">
              <div
                v-html="tgItem.Content.replace(/(?:\r\n|\r|\n)/g, '<br />')"
              ></div>
            </template>
            <template v-else>
              <textarea
                v-model="tgItem.Content"
                placeholder="내용"
                class="form-control"
              />
            </template>
          </div>
        </div>
        <div class="modal-footer justify-content">
          <button
            v-if="tgEditMode == 1"
            type="button"
            class="btn btn-success float-right"
            @click="tgEditMode = 2"
          >
            수정
          </button>
          <button
            v-if="tgEditMode != 1"
            type="button"
            class="btn btn-primary float-right"
            @click="createNoti"
          >
            저장
          </button>
          <button
            v-if="tgEditMode != 0"
            type="button"
            class="btn btn-danger float-right"
            @click="deleteNoti"
          >
            삭제
          </button>
        </div>
      </div>
      <!-- /.modal-content -->
    </div>
    <!-- /.modal-dialog -->
  </div>
</template>
<script>
export default {
  name: "NoticeModal",
  props: { item: Object, editMode: Number },
  components: {},
  data() {
    return { tgItem: null, tgEditMode: null };
  },
  created() {
    this.tgEditMode = this.editMode;
    if (this.editMode == 0) {
      this.tgItem = { Title: "", Content: "" };
    } else {
      this.tgItem = { ...this.item };
    }
  },
  mounted() {
    console.log(this.editMode);
  },
  methods: {
    createNoti() {
      this.$emit("createNotice", this.tgItem);
    },
    deleteNoti() {
      this.$emit("deleteNotice", { Id: this.tgItem.Id });
    },
  },
};
</script>
